import { useDispatch, useSelector, batch } from 'react-redux';
import { useEffect } from 'preact/hooks';
import { FunctionComponent } from 'preact';

import GifPreview from '../shared/GifPreview';
import { Message } from '../../slice/types';

import { sawMessage } from '../../slice/thunks';
import { readMessage, toggleSendTo } from '../../slice/actions';
import { selectFriendsData } from '../../slice/selectors';

import styles from './styles.module.scss';

interface Props {
  message: Message,
  onClose: () => unknown,
}

const FriendMessage: FunctionComponent<Props> = ({ message, onClose }: Props) => {
  const dispatch = useDispatch();

  const friends = useSelector(selectFriendsData);

  const reply = () => {
    batch(() => {
      dispatch(toggleSendTo(message.friendFrom));
      dispatch(readMessage({ id: message.id }));
    });
  };

  const handleClose = () => {
    dispatch(readMessage({ id: message.id }));
    onClose();
  };

  useEffect(() => {
    if (!message.received) {
      dispatch(sawMessage(message));
    }
  }, []);

  const friend = friends.find(({ id }) => id === message.friendFrom);
  const isMp4 = message.imgSrc.endsWith('mp4');

  return (
    <div className={styles.friendsMessage}>
      {isMp4 ? (
        <GifPreview message={message} />
      ) : (
        <img className={styles.image} src={message.imgSrc} alt="" />
      )}

      <div className={styles.description}>
        <p className={styles.text}>
          {friend.isOnline && (
            <>
              <span className={styles.onlineStatus} />{' '}
            </>
          )}
          <i>{friend ? friend.name : '(Deleted friend)'}</i> sent you a GIF
        </p>

        <footer>
          <button className={styles.replyButton} onClick={reply}>
            Reply
          </button>
          <button className={styles.closeButton} onClick={handleClose}>
            Close
          </button>
        </footer>
      </div>
    </div>
  );
};

export default FriendMessage;
